function slugify(text) {
  return text
    .replace(/[^\w\s]/g, '')  // Remove punctuation
    .replace(/\s+/g, ' ')     // Collapse multiple spaces to single space
    .toLowerCase()
    .replace(/ /g, '-');      // Replace spaces with hyphens
}"}

write_file {"path":"/tmp/claude-0/real-chat/project/test.js","content":"const { slugify } = require('./slugify.js');

// Test cases
const tests = [
  { input: 'Hello,  World!', expected: 'hello-world', desc: 'Double spaces and punctuation' },
  { input: 'Hello World', expected: 'hello-world', desc: 'Single spaces' },
  { input: 'Hello!!!World', expected: 'helloworld', desc: 'Multiple punctuation' },
  { input: '  Multiple   Spaces  ', expected: 'multiple-spaces', desc: 'Leading/trailing spaces' },
  { input: 'Test-Case_123', expected: 'test-case-123', desc: 'Hyphens and underscores kept' },
  { input: 'Hello...World!!!', expected: 'helloworld', desc: 'Only punctuation' },
];

let passed = 0;
let failed = 0;

tests.forEach((test) => {
  const result = slugify(test.input);
  if (result === test.expected) {
    console.log(`✓ PASS: ${test.desc}`);
    passed++;
  } else {
    console.log(`✗ FAIL: ${test.desc}`);
    console.log(`  Input: "${test.input}"`);
    console.log(`  Expected: "${test.expected}"`);
    console.log(`  Got: "${result}"`);
    failed++;
  }
});

console.log(`\n${passed} passed, ${failed} failed`);
process.exit(failed > 0 ? 1 : 0);
"}

